package com.hellodoc.service;
import com.hellodoc.dto.*; import com.hellodoc.entity.*; import com.hellodoc.repository.*; import org.springframework.context.ApplicationEventPublisher; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.util.UUID;
@Service public class DoctorApprovalService {
 private final DoctorApplicationRepository applications; private final UserRepository users; private final DoctorProfileService profiles; private final ApplicationEventPublisher events;
 public DoctorApprovalService(DoctorApplicationRepository applications,UserRepository users,DoctorProfileService profiles,ApplicationEventPublisher events){this.applications=applications;this.users=users;this.profiles=profiles;this.events=events;}
 @Transactional public DoctorApplicationSummary approve(UUID id,DecisionRequest request){DoctorApplication a=pending(id);if(!a.hasDoctorDocument())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"L’attestation d’inscription à l’Ordre est obligatoire pour approuver cette candidature.");profiles.createFromApplication(a);a.decide("APPROVED",request==null?null:request.reason());a.getUser().setRoleAndStatus(UserRole.DOCTOR,"ACTIVE");users.save(a.getUser());events.publishEvent(new DoctorApplicationApprovedEvent(a.getUser().getEmail(),a.getUser().getFirstName(),a.getUser().getLastName()));return DoctorApplicationSummary.from(a);}
 @Transactional public DoctorApplicationSummary reject(UUID id,DecisionRequest request){if(request.reason()==null||request.reason().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A reason is required to reject a doctor application.");DoctorApplication a=pending(id);a.decide("REJECTED",request.reason().trim());a.getUser().setRoleAndStatus(UserRole.USER,"REJECTED");return DoctorApplicationSummary.from(a);}
 private DoctorApplication pending(UUID id){DoctorApplication a=applications.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!"PENDING".equals(a.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"This application has already been decided.");return a;}
}
